        { author: "Andrej Scheglov", title: "Kalmarunionen och Krewounionen. Några anmärkningar beträffande de färska studierna av Andrzej Gaca och Hubert Bąk", year: 2025, publisher: "Collegium Medievale", url: "https://ojs.novus.no/index.php/CM/article/download/2478/2467/3639" }
